WAITING = "Alabama, Arkansas, Connecticut, Maine, Maryland, New York, Oregon and Vermont"


def state_tax(code, salary, status="single", pretax=0, fed_tax=0):
    """{"taxable", "tax", "pay": [(name, amount)], "pay_total", "total"} for a yearly salary, as T.stateTax does in assets/tools.js."""
    s, f = STATES[code], STATES[code][status]
    wages = salary if s.get("pretax_taxed") else salary - pretax
    std, ex, credit = f["d"], f["e"], f["c"]
    if s.get("ex_max") and wages > s["ex_max"][status]: ex = 0
    if s.get("ex_steps"): ex = next(a for lim, a in s["ex_steps"] if lim is None or wages <= lim) * (2 if status == "joint" else 1)
    if s.get("std_phase"):
        at, r = s["std_phase"][status]; std = max(0, std - r * max(0, wages - at))
    if s.get("credit_phase"):
        at, r = s["credit_phase"][status]; credit = max(0, credit - r * max(0, wages - at))
    ded = 0
    if s.get("fed_ded"):
        share = next(r for lim, r in s["fed_ded"]["steps"] if lim is None or wages <= lim); ded = min(s["fed_ded"]["cap"][status], share * fed_tax)
    taxable = max(0, salary - pretax - FED_STD[status]) if s["base"] == "fed" else max(0, wages - std - ex - ded)
    tax, lo = 0.0, 0
    for hi, rate in f["b"]:
        top = taxable if hi is None else min(taxable, hi)
        if top > lo: tax += (top - lo) * rate
        if hi is None or taxable <= hi: break
        lo = hi
    if s.get("add_over") and taxable > s["add_over"][0]: tax += s["add_over"][1]
    tax = max(0, tax - credit)
    pay = []
    for name, rate, cap, most in s["pay"]:
        a = rate * (salary if cap is None else min(salary, cap))
        pay.append((name, a if most is None else min(a, most)))
    t = sum(a for _, a in pay)
    return {"taxable": taxable, "tax": tax, "pay": pay, "pay_total": t, "total": tax + t}


HAND = [("NC", 75000, "single", 0, 2483.775, 0), ("GA", 75000, "single", 0, 2994, 0), ("IL", 75000, "single", 0, 3567.7125, 0), ("IL", 300000, "single", 0, 14850, 0), ("PA", 75000, "single", 5000, 2302.5, 52.5),
        ("CA", 75000, "single", 0, 2665.12, 975), ("TX", 75000, "single", 0, 0, 0), ("IA", 75000, "single", 0, 2198.2, 0), ("MT", 75000, "single", 0, 2876.6, 0), ("MS", 75000, "single", 0, 2268, 0),
        ("KY", 75000, "single", 0, 2507.4, 0), ("MA", 75000, "single", 0, 3530, 345), ("NJ", 75000, "single", 0, 2596, 505.4), ("WA", 100000, "single", 0, 0, 1387.2), ("AK", 100000, "single", 0, 0, 271), ("HI", 100000, "joint", 0, None, 390),
        ("MI", 75000, "single", 0, 2936.75, 0), ("CO", 75000, "single", 0, 2591.6, 330), ("OH", 75000, "single", 0, 1619, 0), ("WI", 75000, "single", 0, 2943.52, 0), ("SC", 75000, "single", 0, 2657.32, 0), ("UT", 75000, "single", 0, 3103.45, 0)]


def check():
    for c, s in STATES.items():
        assert s["kind"] in ("none", "flat", "graduated") and s["src"], c
        for st in ("single", "joint"):
            b = s[st]["b"]; assert b[-1][0] is None and all(x[0] < y[0] for x, y in zip(b[:-2], b[1:-1])), (c, st)
            assert all(0 <= r < .14 for _, r in b), (c, st)
    for c, sal, st, pre, tax, pay in HAND:
        r = state_tax(c, sal, st, pre)
        assert tax is None or abs(r["tax"] - tax) < .01, (c, r["tax"], tax)
        assert abs(r["pay_total"] - pay) < .01, (c, r["pay_total"], pay)
    assert abs(state_tax("MO", 75000, "single", 0, 7670)["tax"] - 2533.59) < .01
    return len(STATES)


if __name__ == "__main__":
    print(check(), "states checked")
